<template>
  <main class="lab-page" v-loading="loading">
    <header class="lab-heading"><div><h1>实验专题</h1><p>选择专题，在站场中观察，再完成题目作答。</p></div><div class="heading-actions"><router-link to="/student/history?kind=lab">我的实验记录</router-link><router-link v-if="canReview" :to="user.isAdmin?'/admin/grading':'/teacher/grading'">批阅中心</router-link><button v-if="topicId>=5" @click="showOriginal=true">查看原始站场</button></div></header>
    <p v-if="notice" class="notice" role="alert">{{ notice }}</p>
    <div class="lab-layout"><aside class="course-sidebar"><h2>实验目录</h2><nav aria-label="实验专题目录"><button v-for="topic in topics" :key="topic.id" :class="{active:topic.id===topicId}" :aria-pressed="topic.id===topicId" @click="chooseTopic(topic.id)"><span class="course-number">{{ String(topic.id).padStart(2,'0') }}</span><span><strong>{{ topic.title }}</strong><small>{{ topic.id<=4?'标准站操作观察':'联锁表填写' }}</small></span></button></nav></aside>
    <section class="course-workspace"><header v-if="activeTopic" class="course-heading"><div><span class="course-label">实验 {{ activeTopic.id }}</span><h2>{{ activeTopic.title }}</h2><p>{{ activeTopic.objective }}</p></div><span class="course-count">{{ topicQuestions.length }} 道题</span></header>
      <div v-if="topicQuestions.length" class="question-tabs" aria-label="专题内题目">
        <button v-for="q in topicQuestions" :key="q.key" :class="{active:selectedKey===q.key}" :aria-pressed="selectedKey===q.key" @click="chooseQuestion(q.key)"><span>{{ String(q.sequence).padStart(2,'0') }}</span><Notation :text="q.title"/><small v-if="attempts.some(a=>a.question_id===q.id)">已提交</small></button>
      </div>
      <article v-if="question" class="workspace" :aria-busy="submitting">
        <div class="question-title"><div><span class="tag">{{ question.level }} · {{ question.kinds.join(' / ') }}</span><h2><Notation :text="question.title"/></h2></div><span class="grading-label">客观项 {{ question.automatic_max }} 分<br>教师评阅 {{ question.manual_max }} 分</span></div>
        <p class="prompt"><Notation :text="question.prompt"/></p>
        <aside v-if="question.conditions.length" class="conditions"><strong>本题条件</strong><p v-for="condition in question.conditions" :key="condition"><Notation :text="condition"/></p></aside>
        <section v-if="question.topic<=4" class="standard-observation"><details open><summary>标准站操作观察<span>本题场景独立，操作不会代填答案</span></summary><TheorySimulationConsole :key="question.key" :question-key="question.key" /></details></section>
        <div v-else class="diagram-wrap"><ClassicStationCanvas :answer="emptyDiagram" :focus="focus" reference-mode @inspect="inspect"/><div class="device-readout"><span v-if="focus"><Notation :text="focus.code"/> · {{ deviceDescription }}</span><span v-else>点选设备后，在此查看名称和位置。</span></div></div>
        <form @submit.prevent="submit" class="answer-form">
          <div class="form-caption"><h3>实验作答</h3><details class="answer-help"><summary>填写说明</summary><p>保留（反位）、[防护]、{带动}及 &lt;条件&gt;记号。</p></details></div>
          <fieldset :disabled="submitting">
            <section v-for="(field,index) in question.fields" :key="field.id" :id="`field-${field.id}`" class="answer-field">
              <div class="field-heading"><label :for="`answer-${field.id}`"><span>{{ index+1 }}</span><Notation :text="field.label"/></label><small>{{ field.kind==='essay' ? '教师评阅' : '自动核对' }} · {{ field.points }}分</small></div>
              <div v-if="field.kind==='choice'" class="choice-group" role="radiogroup" :aria-label="field.label"><label v-for="option in field.options" :key="option" :class="{selected:answers[field.id]===option}"><input type="radio" :name="field.id" :value="option" v-model="answers[field.id]"><Notation :text="option"/></label></div>
              <div v-else-if="field.kind==='multi'" class="choice-group"><label v-for="option in field.options" :key="option" :class="{selected:answers[field.id]?.includes(option)}"><input type="checkbox" :value="option" v-model="answers[field.id]"><Notation :text="option"/></label></div>
              <ol v-else-if="field.kind==='order'" class="order-list"><li v-for="(option,i) in answers[field.id]" :key="option"><span>{{ i+1 }}.</span><Notation :text="option"/><button type="button" :aria-label="`上移${option}`" :disabled="i===0" @click="move(field.id,i,-1)">↑</button><button type="button" :aria-label="`下移${option}`" :disabled="i===answers[field.id].length-1" @click="move(field.id,i,1)">↓</button></li></ol>
              <template v-else-if="field.kind==='cell'"><input :id="`answer-${field.id}`" type="text" v-model="answers[field.id]" maxlength="6000" autocomplete="off" placeholder="按本站填写设备和符号"><p v-if="answers[field.id]" class="notation-preview">记号预览：<Notation :text="answers[field.id]"/></p></template>
              <template v-else><textarea :id="`answer-${field.id}`" v-model="answers[field.id]" rows="4" maxlength="6000" placeholder="按工况逐项记录：条件 → 现象 → 原因。区分实测与推测，并写出依据。"></textarea><div class="word-count">{{ (answers[field.id]||'').length }} / 6000</div></template>
            </section>
          </fieldset>
          <div class="submit-row"><p>{{ draftMessage }}<br><small>记录与论述由教师评阅；自动核对结果不代表实验现象已得到验证。</small></p><button type="submit" class="primary-button" :disabled="submitting">{{ submitting?'正在保存…':'提交作答 →' }}</button></div>
        </form>
        <section v-if="result" class="feedback" aria-live="polite" ref="feedbackPanel"><h3>作答已保存 · {{ result.result.status==='pending_review'?'等待教师评阅':'评阅完成' }}</h3><p v-if="result.result.automatic_max">客观项 {{ result.result.automatic_score }} / {{ result.result.automatic_max }} 分<span v-if="result.result.status==='pending_review'">；论述部分尚未计分。</span></p><p v-else>本题为记录与论述题，保存成功后由教师评阅，不自动判定正确或错误。</p><div v-for="item in result.result.feedback" :key="item.id" :class="['feedback-item',item.status]"><strong>{{ item.status==='correct'?'✓':item.status==='incorrect'?'需调整':item.status==='partial'?'部分得分':'待评阅' }} · <Notation :text="item.label"/></strong><template v-if="item.status!=='pending_review'"><p v-for="error in item.errors" :key="error"><Notation :text="error"/></p><p>参考填写：<Notation :text="Array.isArray(item.expected)?item.expected.join(' → '):item.expected" :runs="item.expected_runs"/></p><p><Notation :text="item.explanation"/></p><button v-if="item.status==='incorrect'" @click="locateField(item.id)">回到本栏修改 ↑</button></template><template v-else><p>{{ item.message }}</p><p v-if="item.explanation" class="manual-reference"><Notation :text="item.explanation"/></p><ul><li v-for="point in item.criteria" :key="point">{{ point }}</li></ul></template></div></section>
        <details class="source-note"><summary>实验报告对应位置</summary><p>{{ question.topic_info.report }} · {{ question.source_section }}</p><p>实验专题以本项目原始报告为依据；管理员新增或修订题目按本题标注的命题依据与评分规则评阅，专题1—4使用标准站操作台，专题5—6使用原始图站场。</p></details>
      </article>
      <el-empty v-if="!loading&&!questions.length" description="专题尚未导入"/>

    </section></div>
    <el-dialog v-model="showOriginal" title="原始站场图 · 圈定范围" width="94%" top="3vh"><svg viewBox="0 0 1706 1279" class="original-photo" role="img" aria-label="原始图横向展示"><image :href="originalUrl" width="1279" height="1706" transform="translate(0 1279) rotate(-90)"/></svg></el-dialog>
  </main>
</template>
<script setup>
import { computed, nextTick, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useUserStore } from '@/store/user'
import ClassicStationCanvas from '@/components/ClassicExam/ClassicStationCanvas.vue'
import TheorySimulationConsole from '@/features/simulationConsole/TheorySimulationConsole.vue'
import Notation from '@/components/RailwayNotation.vue'
import { topology } from '@/domain/classicStation'
import { getLabQuestions,getLabQuestion,getLabAttempts,submitLabAnswer } from '@/api/labTopics'
import originalUrl from '../../../../../pictures/原始图.jpg?url'

const route=useRoute(),router=useRouter(),user=useUserStore()
const questions=ref([]),question=ref(null),attempts=ref([]),answers=ref({})
const topicId=ref(1),selectedKey=ref(''),loading=ref(false),submitting=ref(false),notice=ref(''),result=ref(null),focus=ref(null),showOriginal=ref(false),feedbackPanel=ref(null),draftMessage=ref('草稿保存在本机，提交后保存到项目数据库。')
const emptyDiagram={route_buttons:[],switches:{},hostile_signals:[],track_sections:[]}
const canReview=computed(()=>['teacher','admin'].includes(user.role))
const topics=computed(()=>[...new Map(questions.value.map(q=>[q.topic,q.topic_info])).values()])
const activeTopic=computed(()=>topics.value.find(t=>t.id===topicId.value))
const topicQuestions=computed(()=>questions.value.filter(q=>q.topic===topicId.value))
const deviceDescription=computed(()=>{
  const s=topology.signals.find(s=>s.name===focus.value?.code)
  if(s)return `${s.type}信号机 · ${s.track}股道`
  const w=topology.switches.find(w=>w.id===focus.value?.code)
  if(w)return `${w.type} · 连接${w.connects.join('与')}股道`
  const section=topology.sections.find(s=>s.name===focus.value?.code)
  return section?`轨道区段 · ${section.track}股道`:'原图参考设备'
})
let requestId=0, revision=0, initializing=false
function draftKey(q=question.value){return `srtp_lab_${user.user?.id}_${q?.key}_${q?.fingerprint}`}
function inspect(kind,code){focus.value={kind,code}}
function answerText(value){return Array.isArray(value)?value.join(' → '):String(value??'')}
function timeText(value){return new Date(value+'Z').toLocaleString('zh-CN')}
function saveDraft(){if(!question.value||initializing)return;try{localStorage.setItem(draftKey(),JSON.stringify(answers.value));draftMessage.value='草稿已保存到本机。'}catch{draftMessage.value='本机草稿保存失败，请及时提交。'}}
watch(answers,()=>{if(initializing)return;revision++;result.value=null;saveDraft()},{deep:true,flush:'sync'})
function chooseTopic(id){if(submitting.value)return;topicId.value=id;const q=questions.value.find(q=>q.topic===id);if(q)chooseQuestion(q.key)}
async function chooseQuestion(key,updateUrl=true){
  if(submitting.value)return
  saveDraft(); const current=++requestId; loading.value=true;notice.value='';result.value=null;focus.value=null;question.value=null
  try{const q=await getLabQuestion(key);if(current!==requestId)return
    initializing=true;question.value=q;selectedKey.value=key;topicId.value=q.topic
    let draft=null;try{draft=JSON.parse(localStorage.getItem(draftKey(q)))}catch{}
    answers.value=Object.fromEntries(q.fields.map(f=>[f.id,draft?.[f.id]??(f.kind==='multi'?[]:f.kind==='order'?[...f.options]:'')]))
    initializing=false;revision++;draftMessage.value=draft?'已恢复本题草稿。':'草稿保存在本机，提交后保存到项目数据库。'
    if(updateUrl)router.replace({query:{q:key}})
  }catch(e){if(current===requestId)notice.value=message(e,'题目加载失败，可刷新重试。')}
  finally{if(current===requestId)loading.value=false;initializing=false}
}
function move(id,index,offset){const values=[...answers.value[id]];[values[index],values[index+offset]]=[values[index+offset],values[index]];answers.value[id]=values}
function message(e,fallback){const detail=e.response?.data?.detail;return typeof detail==='string'?detail:fallback}
async function submit(){
  if(!question.value||submitting.value)return
  const missing=question.value.fields.find(f=>Array.isArray(answers.value[f.id])?!answers.value[f.id].length:!String(answers.value[f.id]??'').trim())
  if(missing){notice.value='请完成全部答题栏后提交。';locateField(missing.id);return}
  const q=question.value,snapshot=JSON.parse(JSON.stringify(answers.value)),rev=revision
  submitting.value=true;notice.value=''
  try{const response=await submitLabAnswer(q.key,{fingerprint:q.fingerprint,answers:snapshot});attempts.value.unshift(response)
    if(rev===revision&&question.value?.key===q.key){result.value=response;await nextTick();feedbackPanel.value?.scrollIntoView({behavior:'smooth',block:'start'})}
  }catch(e){notice.value=message(e,'提交失败，答案已保留，可重试。')}
  finally{submitting.value=false}
}
function locateField(id){document.getElementById(`field-${id}`)?.scrollIntoView({behavior:'smooth',block:'center'});document.getElementById(`answer-${id}`)?.focus({preventScroll:true})}
watch(()=>route.query.q,key=>{if(typeof key==='string'&&key!==selectedKey.value&&!submitting.value&&questions.value.some(q=>q.key===key))chooseQuestion(key,false)})
onMounted(async()=>{loading.value=true;try{const data=await Promise.all([getLabQuestions(),getLabAttempts()]);questions.value=data[0];attempts.value=data[1];const key=questions.value.find(q=>q.key===route.query.q)?.key||questions.value[0]?.key;if(key)await chooseQuestion(key)}catch(e){notice.value=message(e,'专题加载失败，可刷新重试。')}finally{loading.value=false}})
</script>

<style scoped>
.manual-reference{white-space:pre-line;overflow-wrap:anywhere;line-height:1.9}
.lab-page{width:100%;margin:0;color:#19334d}.lab-header{display:flex;justify-content:space-between;gap:24px;align-items:center;margin-bottom:22px}.overline{color:#337796;font-size:var(--ui-text-meta);letter-spacing:2px;margin:0 0 8px}.lab-header h1{font-size:32px;margin:0 0 10px}.lab-header p:last-child{margin:0;color:#738497;line-height:1.8}.header-actions{display:flex;flex-direction:column;align-items:flex-end;gap:12px}.count{font-size:var(--ui-text-base);color:#52728a}button{font:inherit;border:1px solid #dce6ee;border-radius:6px;padding:8px 12px;background:white;color:#42677e;cursor:pointer}button:disabled{opacity:.5;cursor:default}.mode-tabs{display:flex;gap:8px;border-bottom:1px solid #dfe7ee;margin-bottom:22px;padding-bottom:10px}.mode-tabs button{border:none;background:transparent}.mode-tabs button.active{color:#006fa9;background:#e6f2fa}.mode-tabs span{font-size:var(--ui-text-meta);margin-left:6px}.topic-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.topic-card{display:flex;align-items:center;gap:12px;text-align:left;padding:17px 13px;min-height:88px}.topic-card.active{background:#edf6fc;border-color:#54a0c7;box-shadow:inset 3px 0 #0075b7}.topic-num{font:27px Georgia;color:#586f82}.topic-card strong{display:block;font-weight:600;font-size:var(--ui-text-base);line-height:1.6}.topic-card small{display:block;font-size:var(--ui-text-sm);color:#586f82;margin-top:7px}.topic-arrow{margin-left:auto;color:#586f82}.topic-intro{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:26px 0 18px}.topic-intro h2{font-size:var(--ui-text-heading);margin:0 0 8px}.topic-intro p{font-size:var(--ui-text-base);color:#738497;line-height:1.8;margin:0}.topic-intro>span{font-size:var(--ui-text-meta);white-space:nowrap;color:#586f82}.question-tabs{display:flex;gap:10px;margin-bottom:18px}.question-tabs button{flex:1;text-align:left;display:flex;align-items:center;gap:10px;padding:12px}.question-tabs button>span:first-child{color:#586f82;font-size:var(--ui-text-base)}.question-tabs button.active{border-color:#7fb3d3;color:#006fa9;background:#f4faff}.question-tabs small{color:#528579;font-size:var(--ui-text-sm);white-space:nowrap;margin-left:auto}.workspace{background:white;border:1px solid #dfe7ee;padding:26px;border-radius:10px}.question-title{display:flex;justify-content:space-between;gap:20px;align-items:center}.question-title h2{font-size:25px;margin:12px 0}.tag{font-size:var(--ui-text-meta);color:#407c9a}.grading-label{font-size:var(--ui-text-meta);line-height:1.9;white-space:nowrap;color:#586f82}.prompt{font-size:var(--ui-text-body);line-height:2;color:#50697e;margin:10px 0 18px}.conditions{padding:14px 18px;background:#fff9ee;border:1px solid #eeddbb;border-radius:7px;margin-bottom:18px;font-size:var(--ui-text-base);line-height:1.9;color:#805f34}.conditions p{margin:4px 0}.diagram-wrap{margin:18px 0}.device-readout{padding:11px 14px;border:1px solid #dfe7ee;background:#f5f9fc;border-radius:0 0 6px 6px;font-size:var(--ui-text-base);color:#69849a;min-height:40px}.interval-context{display:flex;align-items:center;flex-wrap:wrap;gap:18px;border:1px dashed #7fa4ba;padding:17px;background:#f4f9fc;border-radius:7px;font-size:var(--ui-text-base)}.interval-line{flex:1;text-align:center;border-bottom:3px double #839cae;font-size:24px}.interval-context small{width:100%;color:#586f82;font-size:var(--ui-text-meta)}.form-caption{display:flex;justify-content:space-between;gap:15px;align-items:baseline;margin-top:25px}.form-caption h3{font-size:var(--ui-text-lead)}.form-caption span{font-size:var(--ui-text-meta);color:#586f82;line-height:1.7}.answer-form fieldset{padding:0;margin:0;border:0;min-width:0}.answer-field{padding:20px 0;border-top:1px solid #e6edf3;scroll-margin-top:24px}.field-heading{display:flex;justify-content:space-between;gap:12px;margin-bottom:12px}.field-heading label{font-size:var(--ui-text-base);color:#405d72;line-height:1.8}.field-heading label>span:first-child{display:inline-block;text-align:center;min-width:22px;margin-right:10px;background:#eaf3f9;color:#4585a3;border-radius:4px}.field-heading small{font-size:var(--ui-text-sm);color:#586f82;white-space:nowrap;line-height:2.4}.choice-group{display:flex;flex-wrap:wrap;gap:10px}.choice-group label{display:flex;align-items:center;gap:8px;border:1px solid #dce5ed;padding:10px 14px;border-radius:6px;font-size:var(--ui-text-base);cursor:pointer}.choice-group label.selected{border-color:#58a0c7;background:#edf7fc}.choice-group input{accent-color:#0075b7}.answer-field input[type=text],textarea{box-sizing:border-box;width:100%;border:1px solid #d3e0e9;border-radius:6px;padding:11px 13px;font:inherit;font-size:var(--ui-text-base);color:#2f4d64;background:#fcfdff;line-height:1.9}textarea{resize:vertical;min-height:110px}.word-count{text-align:right;font-size:var(--ui-text-sm);color:#586f82;margin-top:5px}.notation-preview{font-size:var(--ui-text-base);color:#426c84;margin:10px 0 0}.order-list{list-style:none;margin:0;padding:0;max-width:680px;display:grid;gap:7px}.order-list li{display:flex;align-items:center;gap:12px;background:#f6f9fc;border:1px solid #e4ebf1;border-radius:5px;padding:8px 12px;font-size:var(--ui-text-base)}.order-list li>span:nth-child(2){flex:1}.order-list button{padding:4px 11px}.submit-row{border-top:1px solid #e1e9f0;padding-top:20px;display:flex;align-items:center;justify-content:space-between;gap:18px}.submit-row p{font-size:var(--ui-text-base);color:#597b91;line-height:1.9;margin:0}.submit-row small{color:#586f82}.primary-button{background:#0075b7;border-color:#0075b7;color:white;padding:12px 24px;white-space:nowrap}.notice{background:#fff0e6;border:1px solid #edcdb9;border-radius:7px;padding:12px 15px;color:#995333;font-size:var(--ui-text-base)}.feedback{border-top:1px solid #dce7ef;margin-top:24px;padding-top:18px;scroll-margin-top:20px}.feedback>p{color:#648092;line-height:1.9;font-size:var(--ui-text-base)}.feedback-item{border:1px solid #dfe8ef;border-left:3px solid #91abba;border-radius:5px;background:#fafcfe;padding:14px;margin-top:10px;font-size:var(--ui-text-base);line-height:1.9}.feedback-item.correct{border-left-color:#48a48a}.feedback-item.incorrect{border-left-color:#d08b5c;background:#fffaf5}.feedback-item p{margin:6px 0;color:#627a8d}.feedback-item ul{color:#586f82;margin:6px 0;padding-left:20px}.feedback-item button{font-size:var(--ui-text-meta);padding:4px 8px}.source-note{margin-top:22px;color:#586f82;font-size:var(--ui-text-meta);line-height:1.9}.source-note summary{cursor:pointer}.records-heading{display:flex;justify-content:space-between;align-items:center}.record{margin:16px 0;padding:22px;background:white;border:1px solid #dfe8ef;border-radius:8px;line-height:1.8}.record header{display:flex;justify-content:space-between;gap:15px}.record header span{font-size:var(--ui-text-meta);color:#586f82;white-space:nowrap}.record>small{color:#586f82;font-size:var(--ui-text-meta)}.record details summary{cursor:pointer;font-size:var(--ui-text-base);color:#537c94}.record p{font-size:var(--ui-text-base)}.history-field{padding:15px 0;border-top:1px solid #e7edf2;white-space:pre-wrap;font-size:var(--ui-text-base)}.history-field strong{font-size:var(--ui-text-base)}.history-field input[type=number]{width:80px;border:1px solid #cbdce8;border-radius:4px;padding:7px}.history-field ul{color:#586f82;white-space:normal}.record textarea{margin:9px 0}.teacher-comment{background:#edf6fb;padding:12px;border-radius:5px}.muted{color:#586f82}.original-photo{width:100%;max-height:78vh}button:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid #82bfe0;outline-offset:2px}
